import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink, Router } from '@angular/router';

declare const document: any;
declare const sessionStorage: any;

interface Category { id: string; name: string; desc: string; }

@Component({
  selector: 'app-select-category',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './category.component.html',
  styleUrl: './category.component.css'
})
export class CategoryComponent {
  categories: Category[] = [
    { id: 'Strength', name: 'Musculation', desc: 'Free weights, machines & strength training' },
    { id: 'Pilates', name: 'Pilates', desc: 'Reformer & mat classes for mobility and core' },
  ];
  selected: string | null = null;
  error = '';

  constructor(private router: Router) {}

  select(id: string): void {
    this.selected = id;
    this.error = '';
  }

  continue(): void {
    if (!this.selected) {
      this.error = 'Please select a category';
      return;
    }
    sessionStorage.setItem('signup_category', this.selected);
    this.router.navigate(['/select-plan']);
  }
}
<div class="auth-body">
<div class="auth">
  <div class="auth__visual" id="auth-visual">
    <div class="auth__scrim"></div>
    <div class="auth__visual-content">
      <a class="auth__brand" routerLink="/"><img src="assets/logo.svg" alt="EOS" height="25" style="display:block;"></a>
      <div class="auth__caption">
        <p class="auth__caption-eyebrow">Almost there</p>
        <h2>What do you want to train?</h2>
        <p>Pick the program you'd like to join.</p>
      </div>
    </div>
  </div>

  <div class="auth__panel">
    <div class="auth__navbar">
      <a class="auth__navbar-brand" routerLink="/"><img src="assets/logo.svg" alt="EOS"></a>
    </div>

    <div class="auth__panel-scroll">
    <div class="auth__card">
      <div class="auth__head">
        <h1>Choose your category</h1>
        <p>Select the program you'd like to join</p>
      </div>

      <div class="category-grid">
        <button type="button" class="category-card"
                *ngFor="let c of categories"
                [class.category-card--active]="selected === c.id"
                (click)="select(c.id)">
          <span class="category-card__name">{{ c.name }}</span>
          <span class="category-card__desc">{{ c.desc }}</span>
        </button>
      </div>

      <span class="field__error" [class.field__error--show]="error">{{ error }}</span>

      <button type="button" class="auth-form__submit" id="category-continue" (click)="continue()">
        <svg class="spinner" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"><path d="M21 12a9 9 0 1 1-9-9"/></svg>
        <span class="btn-label">Continue</span>
      </button>
    </div>
    </div>
  </div>
</div>
</div>
